          <strong id="sessionTitle">{{ $sesi ? $sesi->jadwal->mapel->nama_mapel.' • '.$sesi->jadwal->kelas->nama_kelas : 'Pilih jadwal untuk memulai sesi' }}</strong>
          <span class="qr-countdown" id="qrCountdown" role="timer" aria-live="polite">QR belum aktif</span>
          <small id="qrExpiry">{{ $sesi?->qr_expires_at?->format('H:i:s') ?? 'QR akan berlaku 5 menit' }}</small>
        </div>
        <div class="qr-actions"><div class="attendance-tally" id="attendanceCounts" aria-live="polite">Belum ada sesi aktif</div><div class="session-buttons"><button class="btn btn-primary refresh-qr" id="refreshQr" type="button" {{ $sesi?->status_sesi === 'Berlangsung' ? '' : 'disabled' }}>🔄 Perbarui QR Code (5 Menit)</button><button class="btn btn-close-session" id="closeSession" type="button" {{ $sesi?->status_sesi === 'Berlangsung' ? '' : 'disabled' }}>⛔ Tutup Sesi &amp; Simpan</button></div></div>
      </div>
      <div class="panel"><div class="panel-head"><div class="panel-title">Daftar Presensi Murid</div><span class="muted" id="syncStatus">Menunggu sesi dimulai</span></div><div class="student-grid" id="studentList"><p class="empty-attendance">Buka sesi untuk menampilkan daftar murid.</p></div></div>
