<dialog class="session-confirm" id="closeConfirm" aria-labelledby="closeConfirmTitle"><div class="confirm-content"><span class="confirm-icon">!</span><h2 id="closeConfirmTitle">Tutup sesi presensi?</h2><p>Apakah Anda yakin ingin menutup sesi? Siswa yang belum absen akan otomatis tercatat <strong>ALFA</strong>.</p><div class="confirm-actions"><button class="btn" id="cancelClose" type="button">Kembali</button><button class="btn btn-close-session" id="confirmClose" type="button">Ya, Tutup Sesi &amp; Simpan</button></div></div></dialog>
<script>
window.addEventListener('load',()=>setTimeout(()=>{pageLoader.classList.add('hide');guruPage.classList.add('loaded')},500));
function toggleSidebar(){sidebar.classList.toggle('open');sidebarOverlay.classList.toggle('show');burgerBtn.classList.toggle('active')}
function updateLiveDatetime(){const n=new Date(),d=['Minggu','Senin','Selasa','Rabu','Kamis','Jumat','Sabtu'],m=['Januari','Februari','Maret','April','Mei','Juni','Juli','Agustus','September','Oktober','November','Desember'],p=x=>String(x).padStart(2,'0');liveDatetime.textContent=`${d[n.getDay()]}, ${n.getDate()} ${m[n.getMonth()]} ${n.getFullYear()} | ${p(n.getHours())}:${p(n.getMinutes())}:${p(n.getSeconds())} WIB`}
updateLiveDatetime();setInterval(updateLiveDatetime,1000);
const panel=document.getElementById('sessionPanel'),feedback=document.getElementById('feedback'),csrf=document.querySelector('meta[name="csrf-token"]')?.content,closeConfirm=document.getElementById('closeConfirm');
let lastRowsFingerprint='',pollingTimer=null,expiryTimer=null,feedbackTimer=null;
async function requestJson(url,method='GET',body=null){const response=await fetch(url,{method,headers:{'Accept':'application/json','Content-Type':'application/json','X-CSRF-TOKEN':csrf},body:body?JSON.stringify(body):undefined});const data=await response.json();if(!response.ok)throw new Error(data.message||Object.values(data.errors||{}).flat()[0]||'Permintaan gagal.');return data}
function showFeedback(type,message){clearTimeout(feedbackTimer);feedback.className=`feedback-message is-${type} is-visible`;feedback.textContent=message;feedbackTimer=setTimeout(()=>feedback.classList.remove('is-visible'),type==='error'?6500:4200)}
function showError(error){showFeedback('error',error.message)}
function showSuccess(message){showFeedback('success',message)}
function updateScheduleRow(data){const jadwalId=data.jadwal_id||data.jadwal?.id;if(!jadwalId)return;const row=document.querySelector(`tr[data-jadwal-id="${jadwalId}"]`);if(!row)return;const state=row.querySelector('[data-session-state]');state.textContent=data.status_sesi;state.classList.remove('is-live','is-done','is-idle');state.classList.add(data.status_sesi==='Berlangsung'?'is-live':data.status_sesi==='Selesai'?'is-done':'is-idle');const action=row.querySelector('[data-session-action]');action.replaceChildren();if(data.status_sesi==='Berlangsung'){const link=document.createElement('a');link.className='btn btn-primary';link.href=panel.dataset.manageTemplate.replace('__ID__',data.id);link.textContent='Kelola Sesi';action.append(link)}else if(data.status_sesi==='Selesai'){const label=document.createElement('span');label.className='muted';label.textContent='Selesai';action.append(label)}}
function renderStudents(rows){const fingerprint=JSON.stringify(rows);if(fingerprint===lastRowsFingerprint)return;lastRowsFingerprint=fingerprint;const list=document.getElementById('studentList');list.replaceChildren();const counts={Hadir:0,Izin:0,Sakit:0,Alfa:0,'Belum Absen':0};const statusClasses={Hadir:'hadir',Izin:'izin',Sakit:'sakit',Alfa:'alfa','Belum Absen':'belum-absen'};rows.forEach(row=>{counts[row.status]=(counts[row.status]||0)+1;const line=document.createElement('div');line.className=`student-row is-${statusClasses[row.status]||'belum-absen'}`;line.innerHTML='<div class="student-identity"><div><span class="student-name"></span><span class="student-id"></span></div><span class="attendance-status"></span></div><div class="radio-group"></div>';line.querySelector('.student-name').textContent=row.nama;line.querySelector('.student-id').textContent=row.nisn;line.querySelector('.attendance-status').textContent=row.status;line.setAttribute('aria-label',`${row.nama}, ${row.status}`);const radios=line.querySelector('.radio-group');['Hadir','Izin','Sakit','Alfa'].forEach(status=>{const label=document.createElement('label'),input=document.createElement('input');input.type='radio';input.name=`status-${row.id}`;input.value=status;input.checked=row.status===status;input.disabled=document.getElementById('sessionStatus').textContent!=='Berlangsung';input.addEventListener('change',async()=>{try{await requestJson(panel.dataset.manualTemplate.replace('__ID__',row.id),'PUT',{status});lastRowsFingerprint='';await refreshStatus();showSuccess('Status presensi tersimpan.')}catch(error){showError(error)}});label.append(input,document.createTextNode(` ${status}`));radios.append(label)});list.append(line)});document.getElementById('attendanceCounts').textContent=`Hadir ${counts.Hadir||0} dari ${rows.length} murid • Izin ${counts.Izin||0} • Sakit ${counts.Sakit||0} • Alfa ${counts.Alfa||0} • Belum ${counts['Belum Absen']||0}`}
function setExpiry(value){panel.dataset.qrExpiresAt=value||'';document.getElementById('qrExpiry').textContent=value?`Berlaku sampai ${new Date(value).toLocaleTimeString('id-ID')}`:'QR tidak aktif';updateCountdown()}
function updateCountdown(){const expiry=Date.parse(panel.dataset.qrExpiresAt||'');const seconds=Math.ceil((expiry-Date.now())/1000);const expired=!Number.isFinite(expiry)||seconds<=0;const visual=document.getElementById('qrVisual'),overlay=document.getElementById('qrExpiredOverlay'),refresh=document.getElementById('refreshQr'),countdown=document.getElementById('qrCountdown');visual.classList.toggle('is-expired',expired);countdown.classList.toggle('is-expired',expired);overlay.hidden=!expired||document.getElementById('sessionStatus').textContent!=='Berlangsung';if(expired){countdown.textContent='QR Kadaluarsa';refresh.classList.add('needs-refresh')}else{countdown.textContent=`QR Aktif: ${String(Math.floor(seconds/60)).padStart(2,'0')}:${String(seconds%60).padStart(2,'0')}`;refresh.classList.remove('needs-refresh')}}
function updateState(data){const status=document.getElementById('sessionStatus');status.textContent=data.status_sesi;status.classList.remove('is-live','is-done','is-idle');status.classList.add(data.status_sesi==='Berlangsung'?'is-live':data.status_sesi==='Selesai'?'is-done':'is-idle');document.getElementById('refreshQr').disabled=data.status_sesi!=='Berlangsung';document.getElementById('closeSession').disabled=data.status_sesi!=='Berlangsung';document.getElementById('syncStatus').textContent=data.status_sesi==='Berlangsung'?'Pembaruan otomatis setiap 3 detik':data.status_sesi;if(data.jadwal)document.getElementById('sessionTitle').textContent=`${data.jadwal.mapel} • ${data.jadwal.kelas}`;if(data.jadwal_id||data.jadwal?.id)updateScheduleRow(data);if(data.qr_expires_at!==undefined)setExpiry(data.qr_expires_at);renderStudents(data.presensi||[]);updateCountdown()}
function showQr(data){document.getElementById('qrImage').innerHTML=data.qr_svg;setExpiry(data.qr_expires_at);updateState(data)}
async function refreshStatus(){if(!panel.dataset.statusUrl)return;try{updateState(await requestJson(panel.dataset.statusUrl))}catch(error){document.getElementById('syncStatus').textContent='Koneksi terputus, mencoba lagi...';showError(error)}}
function startPolling(){clearInterval(pollingTimer);pollingTimer=setInterval(refreshStatus,3000)}
document.querySelectorAll('.open-session').forEach(button=>button.addEventListener('click',async()=>{button.disabled=true;try{const data=await requestJson(button.dataset.url,'POST',{jadwal_pelajaran_id:button.dataset.jadwalId});panel.dataset.sessionId=data.id;const statusPath=new URL(button.dataset.url,window.location.href).pathname.replace(/\/sesi\/[^/]+\/buka$/,'/sesi/'+data.id+'/status');panel.dataset.statusUrl=window.location.origin+statusPath;document.getElementById('sessionTitle').textContent=`${data.jadwal.mapel} • ${data.jadwal.kelas}`;showQr(data);showSuccess('Sesi berhasil dibuka. QR aktif selama 5 menit.');await refreshStatus();startPolling()}catch(error){showError(error);button.disabled=false}}));
document.getElementById('refreshQr').addEventListener('click',async()=>{if(!panel.dataset.sessionId)return;const button=document.getElementById('refreshQr');button.disabled=true;try{const data=await requestJson(panel.dataset.qrTemplate.replace('__ID__',panel.dataset.sessionId),'POST');showQr(data);showSuccess('QR Code diperbarui dan aktif 5 menit lagi.')}catch(error){showError(error)}finally{button.disabled=document.getElementById('sessionStatus').textContent!=='Berlangsung'}});
document.getElementById('closeSession').addEventListener('click',()=>closeConfirm.showModal());document.getElementById('cancelClose').addEventListener('click',()=>closeConfirm.close());closeConfirm.addEventListener('click',event=>{if(event.target===closeConfirm)closeConfirm.close()});
document.getElementById('confirmClose').addEventListener('click',async()=>{const button=document.getElementById('confirmClose');button.disabled=true;try{const data=await requestJson(panel.dataset.closeTemplate.replace('__ID__',panel.dataset.sessionId),'POST');document.getElementById('qrImage').replaceChildren();updateState(data);closeConfirm.close();showSuccess('Sesi ditutup. Siswa yang belum absen telah tercatat Alfa.');clearInterval(pollingTimer)}catch(error){showError(error)}finally{button.disabled=false}});
if(panel.dataset.statusUrl){refreshStatus();startPolling()}setExpiry(panel.dataset.qrExpiresAt);expiryTimer=setInterval(updateCountdown,1000);
</script>
</body></html>
